      position: absolute;
      top: 1rem;
      left: 1rem;
      transform: translateY(-200%);
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: var(--text);
      color: var(--bg);
      font-weight: 700;
      transition: transform 160ms ease;
    }

