      margin-bottom: 1rem;
      color: var(--text);
      font-size: 1.125rem;
      font-weight: 800;
    }

    .required {
      color: var(--accent-strong);
      font-weight: 800;
    }

    .hint {
      margin: -0.5rem 0 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .options {
      display: grid;
      gap: 0.875rem;
    }

    .option {
      display: flex;
      align-items: center;
      gap: 0.875rem;
      padding: 1rem;
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: var(--panel);
      color: var(--text);
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .option:hover {
      border-color: var(--accent-strong);
      background: var(--panel-strong);
      transform: translateY(-1px);
    }

    .option input {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0;
      accent-color: var(--accent-strong);
      flex: 0 0 auto;
