      --accent: #7c3aed;
      --accent-strong: #a78bfa;
      --border: #334155;
      --success: #86efac;
      --error: #fca5a5;
      --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 2rem;
      background:
        radial-gradient(circle at top left, rgba(124, 58, 237, 0.35), transparent 36rem),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.22), transparent 32rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
    }

    .skip-link {
      position: absolute;
      top: 1rem;
      left: 1rem;
      transform: translateY(-200%);
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: var(--text);
      color: var(--bg);
      font-weight: 700;
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      width: min(100%, 36rem);
    }

    .card {
      padding: clamp(1.5rem, 5vw, 3rem);
      border: 1px solid var(--border);
      border-radius: 1.5rem;
      background: linear-gradient(145deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.92));
      box-shadow: var(--shadow);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(2rem, 8vw, 3rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .intro {
      margin: 0 0 2rem;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .form-field {
      margin: 0 0 1.5rem;
      padding: 1.25rem;
      border: 1px solid var(--border);
      border-radius: 1.25rem;
      background: rgba(15, 23, 42, 0.72);
    }

    fieldset {
      min-width: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin-bottom: 1rem;
      color: var(--text);
      font-size: 1.125rem;
      font-weight: 800;
    }

    .required {
      color: var(--accent-strong);
      font-weight: 800;
    }

    .hint {
      margin: -0.5rem 0 1rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .options {
      display: grid;
      gap: 0.875rem;
    }

    .option {
      display: flex;
      align-items: center;
      gap: 0.875rem;
      padding: 1rem;
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: var(--panel);
      color: var(--text);
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .option:hover {
      border-color: var(--accent-strong);
      background: var(--panel-strong);
      transform: translateY(-1px);
    }

    .option input {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0;
      accent-color: var(--accent-strong);
      flex: 0 0 auto;
    }

    .option:has(input:checked) {
      border-color: var(--accent-strong);
      background: rgba(124, 58, 237, 0.22);
      box-shadow: inset 0 0 0 1px var(--accent-strong);
    }

    .option:has(input:focus-visible) {
      outline: 3px solid transparent;
      box-shadow: 0 0 0 3px var(--bg), 0 0 0 6px var(--accent-strong);
    }

    button {
      width: 100%;
      min-height: 3.25rem;
      border: 0;
      border-radius: 1rem;
      background: linear-gradient(135deg, var(--accent), #2563eb);
      color: #ffffff;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: filter 160ms ease, transform 160ms ease;
    }

    button:hover {
      filter: brightness(1.08);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid transparent;
      box-shadow: 0 0 0 3px var(--bg), 0 0 0 6px var(--accent-strong);
    }

    .message {
      min-height: 1.5rem;
      margin: 1rem 0 0;
      color: var(--success);
      font-weight: 700;
    }

    .message.error {
      color: var(--error);
    }

    @media (max-width: 24rem) {
      body {
        padding: 1rem;
      }

      .card,
      .form-field {
        border-radius: 1rem;
      }
