<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Notification Preferences</h1>
      <p class="intro">Choose how you would like us to keep you informed.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset>
            <legend>
              How do you prefer to receive notifications?
              <span class="required" aria-hidden="true">*</span>
            </legend>
            <p class="hint" id="notification-hint">Select one option.</p>

            <div class="options">
              <label class="option">
                <input type="radio" name="notification" value="Email" required aria-describedby="notification-hint form-message">
                <span>Email</span>
              </label>
              <label class="option">
                <input type="radio" name="notification" value="SMS" required aria-describedby="notification-hint form-message">
                <span>SMS</span>
              </label>
              <label class="option">
                <input type="radio" name="notification" value="Push Notifications" required aria-describedby="notification-hint form-message">
                <span>Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <button type="submit">Submit preference</button>
        <p class="message" id="form-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const message = document.querySelector("#form-message");
    const notificationInputs = Array.from(document.querySelectorAll('input[name="notification"]'));

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedOption = notificationInputs.find((input) => input.checked);

      if (!selectedOption) {
        message.textContent = "Please choose how you prefer to receive notifications.";
        message.classList.add("error");
        notificationInputs.forEach((input) => input.setAttribute("aria-invalid", "true"));
        notificationInputs[0].focus();
        return;
      }

      notificationInputs.forEach((input) => input.removeAttribute("aria-invalid"));
      message.textContent = `Preference saved: ${selectedOption.value}.`;
      message.classList.remove("error");
    });

    notificationInputs.forEach((input) => {
      input.addEventListener("change", () => {
        notificationInputs.forEach((radio) => radio.removeAttribute("aria-invalid"));
        message.textContent = "";
        message.classList.remove("error");
      });
    });
  </script>
</body>
